              <>
                <UserPlus className="h-6 w-6 text-indigo-600" />
                <span>Create Academic Account</span>
              </>
            ) : (
              <>
                <LogIn className="h-6 w-6 text-indigo-600" />
                <span>Sign In</span>
              </>
            )}
          </h1>
          <p className="text-gray-500 text-sm mt-1">
            {isRegisterMode
