                className="text-indigo-600 font-bold hover:underline cursor-pointer"
                aria-label="Switch to Sign In mode"
              >
                Sign In
              </button>
            </p>
          ) : (
            <p className="text-gray-600">
              New visitor?{' '}
              <button
                onClick={() => {
                  setIsRegisterMode(true);
                  setLocalErrors({});
                  setApiError(null);
                }}
                className="text-indigo-600 font-bold hover:underline cursor-pointer"
                aria-label="Switch to Register account mode"
              >
                Create Account
              </button>
            </p>
          )}
        </div>
      </div>
    </main>
  );
};

